import socket,threading,sqlite3,re,time,json,os
DB='/var/lib/huddle/huddle.db'; clients=[]; lock=threading.Lock()
def user(t):
 c=sqlite3.connect(DB);r=c.execute('SELECT u.id,u.username FROM users u JOIN tokens t ON u.id=t.user_id WHERE t.token=?',(t,)).fetchone();c.close();return r
def chan(n):
 m=re.fullmatch(r'#([^/]+)/([^/]+)',n)
 if not m:return None
 c=sqlite3.connect(DB);r=c.execute('SELECT c.*,w.slug FROM channels c JOIN workspaces w ON c.workspace_id=w.id WHERE w.slug=? AND c.name=?',(m[1],m[2])).fetchone();c.close();return r
def client(s):
 tok=None; nick=None; u=None; joined=[]
 def send(x):s.sendall((x+'\r\n').encode())
 def numeric(n,text):send(':huddle '+str(n)+' '+(nick or '*')+' '+text)
 try:
  f=s.makefile()
  for line in f:
   a=line.rstrip('\r\n'); sp=a.split(' ',2); cmd=sp[0].upper()
   if cmd=='PASS':tok=sp[1] if len(sp)>1 else '';u=user(tok); numeric(464,'Password incorrect') if not u else None
   elif cmd=='NICK':
    nn=sp[1] if len(sp)>1 else ''
    with lock: collision=any(x[1]==nn for x in clients)
    if collision:numeric(433,'Nickname in use')
    else:nick=nn
   elif cmd=='USER' and u and nick:
    for n,t in [(1,'Welcome'),(2,'Your host'),(3,'Created'),(4,'huddle'),(5,'CHATHOOD')]:numeric(n,t)
    numeric(422,'MOTD File is missing')
    with lock:clients.append((s,nick,u[0],u[1],joined))
   elif cmd=='PING':send('PONG :'+(sp[-1].lstrip(':') if len(sp)>1 else ''))
   elif cmd=='JOIN' and len(sp)>1:
    ch=chan(sp[1])
    if not ch:numeric(403,'No such channel')
    else:
     joined.append(ch['id']);send(':'+nick+'!'+u[1]+'@localhost JOIN '+sp[1]);numeric(353,'= '+sp[1]+' :'+nick);numeric(366,sp[1]+' End of NAMES')
   elif cmd in ('NAMES','WHO','LIST','TOPIC','MODE'):numeric(323,'OK')
   elif cmd=='PRIVMSG' and len(sp)>2:
    ch=chan(sp[1]); body=sp[2].lstrip(':')
    if ch:
     c=sqlite3.connect(DB);c.execute('INSERT INTO messages(channel_id,author_id,body,created_at) VALUES(?,?,?,datetime("now"))',(ch['id'],u[0],body));i=c.execute('SELECT last_insert_rowid()').fetchone()[0];q=c.execute('SELECT COALESCE(MAX(event_id),0)+1 FROM events WHERE channel_id=?',(ch['id'],)).fetchone()[0];c.execute('INSERT INTO events(channel_id,event_id,kind,payload) VALUES(?,?,?,?)',(ch['id'],q,'message.created',json.dumps({'message_id':i,'body':body,'author_id':u[0]})));c.commit();c.close()
   elif cmd=='QUIT':break
   else:numeric(421,'Unknown command')
 except:pass
 finally:
  with lock:
   for x in clients[:]:
    if x[0] is s:clients.remove(x)
  s.close()
def main():
 z=socket.socket();z.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,1);z.bind(('0.0.0.0',6667));z.listen()
 while 1:
  s,_=z.accept();threading.Thread(target=client,args=(s,),daemon=True).start()
main()
